import com.luci.pianoroom.*;
public final class PianoBodyJniTest {
 public static void main(String[] args)throws Exception{long bank=Synth.load(args[0]);if(bank==0)throw new AssertionError("bank");Synth synth=new Synth();try{synth.setLayer(0,bank,0);synth.setGain(0,.4f);if(args.length>1)synth.backend(1);ChannelSettings c=synth.channels[0];c.bodyEnabled=true;c.bodyAmount=18;c.boardAmount=22;c.lid=70;synth.channelChange(0);synth.start();Thread.sleep(200);synth.midi(0x90,60,100);Thread.sleep(80);if(synth.voicesNow()[0]==0)throw new AssertionError("native engine sounds");for(int n=0;n<25;n++){c.bodySize=n*4;c.boardDamping=100-n*4;c.lid=n*4;synth.channelChange(0);Thread.sleep(3);}c.bodyEnabled=false;synth.channelChange(0);synth.midi(0x80,60,0);synth.panic();if(!synth.isRunning())throw new AssertionError("stream lost");System.out.println("PASS: actual Synth/JNI body enable/live controls/disable/panic on "+(args.length>1?"simulated AAudio":"simulated AudioTrack")+".");}finally{synth.close();Synth.freeBank(bank);}}
}
